import{_ as a,o as e,c as o,ai as s}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"创建第一个 Bot","description":"从新建、起名到第一条消息，十分钟搭好一个真正能用的 Bot。","frontmatter":{"related":["/start/brief-tasks-clearly","/start/five-things-day-one","/basics/memory-preferences"],"title":"创建第一个 Bot","description":"从新建、起名到第一条消息，十分钟搭好一个真正能用的 Bot。","section":"start","order":2,"tags":["入门","创建","设置"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/overview"],"wordCount":538,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"创建第一个 Bot | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"从新建、起名到第一条消息，十分钟搭好一个真正能用的 Bot。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/start/create-first-bot"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/start-create-first-bot-4016316e98.png"}],["meta",{"property":"og:image:alt","content":"创建第一个 Bot · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"创建第一个 Bot | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"从新建、起名到第一条消息，十分钟搭好一个真正能用的 Bot。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/start-create-first-bot-4016316e98.png"}],["meta",{"name":"twitter:image:alt","content":"创建第一个 Bot · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/start/create-first-bot"}]]},"headers":[],"relativePath":"start/create-first-bot.md","filePath":"start/create-first-bot.md","lastUpdated":1792485206000}'),n={name:"start/create-first-bot.md"};function i(r,t,p,l,c,d){return e(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="创建第一个-bot" tabindex="-1">创建第一个 Bot <a class="header-anchor" href="#创建第一个-bot" aria-label="Permalink to &quot;创建第一个 Bot&quot;">​</a></h1><p>很多新手建的第一个 Bot 叫&quot;助手&quot;或&quot;通用 Bot&quot;，什么都让它做，结果它什么都记不住重点。更好的做法是：<strong>第一个 Bot 就给它一份明确的工作</strong>。</p><h2 id="第一步-想好它的-岗位" tabindex="-1">第一步：想好它的&quot;岗位&quot; <a class="header-anchor" href="#第一步-想好它的-岗位" aria-label="Permalink to &quot;第一步：想好它的&quot;岗位&quot;&quot;">​</a></h2><p>先回答三个问题，写在便签上就行：</p><ol><li>它负责什么？（比如：每天帮我整理收件箱里的重要邮件）</li><li>它要用到哪些工具？（比如：Gmail、日历）</li><li>哪些事它不能自己做主？（比如：不能替我回复、不能删邮件）</li></ol><p>一个 Bot 值得单独存在，通常是因为它有独立的目标、工具、做事风格或固定时间表。</p><h2 id="第二步-新建并起名" tabindex="-1">第二步：新建并起名 <a class="header-anchor" href="#第二步-新建并起名" aria-label="Permalink to &quot;第二步：新建并起名&quot;">​</a></h2><p>在应用侧边栏选择新建对话，然后选择创建新 Bot（具体按钮文字可能随版本变化，以官方最新说明为准）。名字建议直接用岗位，比如&quot;收件箱管家&quot;&quot;内容编辑&quot;&quot;周报助手&quot;。之后点击对话顶部的 Bot 名称，可以改名字、头像和描述。</p><h2 id="第三步-发一条-入职说明" tabindex="-1">第三步：发一条&quot;入职说明&quot; <a class="header-anchor" href="#第三步-发一条-入职说明" aria-label="Permalink to &quot;第三步：发一条&quot;入职说明&quot;&quot;">​</a></h2><p>第一条消息别只说&quot;你好&quot;。把岗位、来源和边界一次讲清楚，并请它记住：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的岗位是&quot;收件箱管家&quot;。</span></span>
<span class="line"><span>职责：每天帮我梳理 Gmail 里需要我处理的邮件，按&quot;今天必须回 / 本周内处理 / 仅供知晓&quot;三类整理。</span></span>
<span class="line"><span>工具：Gmail（如果还没连接，请提示我授权）。</span></span>
<span class="line"><span>边界：不要替我发送任何邮件，不要删除或归档邮件；需要回复的，先写草稿给我看。</span></span>
<span class="line"><span>输出：中文，用表格，每封邮件附一句话摘要和原邮件链接。</span></span>
<span class="line"><span>请把以上内容记住，作为你的长期工作规则。</span></span></code></pre></div><h2 id="第四步-马上给一个真实的小任务" tabindex="-1">第四步：马上给一个真实的小任务 <a class="header-anchor" href="#第四步-马上给一个真实的小任务" aria-label="Permalink to &quot;第四步：马上给一个真实的小任务&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>现在先试一次：看看过去 48 小时的邮件，按上面的规则整理给我。</span></span></code></pre></div><p>第一次跑完后，你多半会想调整：分类太粗、摘要太长、漏了某类发件人。直接告诉它，并说明&quot;以后都这样&quot;：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以后来自财务和法务的邮件一律放进&quot;今天必须回&quot;。摘要控制在 30 字以内。请记住。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">授权时别慌</p><p>Bot 第一次需要用某个应用时，会在对话里弹出连接卡片。按提示在浏览器里完成官方登录授权即可，你的密码不会出现在聊天记录里。</p></div><div class="warning custom-block"><p class="custom-block-title">别把 Bot 当保险箱</p><p>同一账号下的所有 Bot 共用一台云电脑，文件和网站登录状态是互通的。分成多个 Bot 是为了分工，不是为了隔离权限。</p></div><h2 id="整理你的-bot-列表" tabindex="-1">整理你的 Bot 列表 <a class="header-anchor" href="#整理你的-bot-列表" aria-label="Permalink to &quot;整理你的 Bot 列表&quot;">​</a></h2><p>Bot 多了以后，可以把常用的置顶，按项目或用途分组；暂时不用的可以隐藏，隐藏不会删除它的工作，也不会暂停它的例程。</p>`,19)])])}const m=a(n,[["render",i]]);export{h as __pageData,m as default};
